from collections import deque

def is_stack_exterminable(s):
    stack = deque()
    for i, num in enumerate(s):
        if not stack or stack[-1] != num:
            stack.append(num)
        else:
            stack.pop()
    return not stack

def count_stack_exterminable_subarrays(arr):
    count = 0
    n = len(arr)
    for i in range(n):
        if i > 0 and i < n-1:
            for l in range(i+1, n+1):
                s = arr[i:l]
                if is_stack_exterminable(s):
                    count += 1
    return count

