def find_next_pos(x, y, sensors, c):
    for u, v in sensors:
        if abs(u - x) + abs(v - y) <= c:
            break
    else:
        return None
    if abs(u - x) < c and (u, v) == (1, 1):  # If the position is on the initial point
        return (1, 1)
    if abs(v - y) < c and (u, v) == (n, n):  # If the position is on the final point
        return (n, n)
    for step in (x - 1, y + 1):
        if abs(step) < c:
            return (x, y + step) + (x - step, y)
    return None

