    ab = (py2-py1)*(px4-px2)-(px2-px1)*(py4-py2)

    # If any of the endpoints is a common vertex
    if (px1 == px4) ^ (py1 == py4):
        if intersection(a, b, (py2-py1), (px2-px1), px1, py1) == pixel:
            return True

        ab /= (px2-px1)
