import bisect

class RobotTerritory:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.terr = [[0] * width for _ in range(height)]

    def add_robot(self, dir, x, y, length):
        if dir == 1 or dir == 4:
            for i in range(length + 1):
                self.terr[y][x + i] = 1
                self.terr[y][x - length - 1 - i] = 1
        elif dir == 2 or dir == 3:
            for i in range(length + 1):
                self.terr[y][x + i] = 1
                self.terr[y + length + 1 - i][x + i] = 1

    def count_robots_at(self, x, y):
        count = 0
        for i in range(1, self.width):
            for j in range(1, self.height):
                if (self.terr[y + i][x] or self.terr[y - i][x]) and (self.terr[y][x + j] or self.terr[y][x - j]):
                    count += 1
        return count

def solve(R): 
