def add_edges_to_tree(N, edges):
    tree = [[] for _ in range(N+1)]
    for edge in edges:
        tree[edge[1]].append(edge[0])
    return tree

def find_diameter(N, tree):
    def find(root):
        if tree[root][0] == -2:
            return root
        p = find(tree[root][0])
        tree[root][0] = p
        return p

    def distance(r1, r2):
        root1 = find(r1)
        root2 = find(r2)
        if root1 == root2:
            return 0
        path_to_root1 = tree[root1]
        path_to_root2 = tree[root2]
        while path_to_root1 and path_to_root2:
            p1 = find(path_to_root1.pop(0))
            p2 = find(path_to_root2.pop(0))
            if p1 == p2:
                return -len(path_to_root1) + len(path_to_root2)
            tree[p1] = path_to_root1 + path_to_root2
            break
        r1 = r1 == root1
        r2 = r2 == root2
        if r1 and r2:
            return -len(path_to_root1) + len(path_to_root2)
        if r1:
            return -len(path_to_root1)
        return -len(path_to_root2)

    result = []
    for r1 in range(2, N+1):
        r2 = r1
        while True:
            d = distance(r1, r2)
            result.append(d)
            if d < 0:
                r2 += r2 > r1
            else:
                r1 += r2 > r1
    return result

