import math
import sys

def get_distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def get_intersection_length(polygon, line):
    x1, y1 = polygon[0]
    x2, y2 = polygon[1]
    slope = (y2 - y1) / (x2 - x1)

    # Equation of the line: y = slope * x + c
    c = y1 - slope * x1
    d = -slope

    first_intersection = sys.float_info.max
    second_intersection = sys.float_info.max
    first_is_real = False
    second_is_real = False

    if abs(slope) < 1e-5:
        # Parallel lines case
        # If triangle formed by second point and intersection is not degenerate
        if get_distance(line, polygon) > 0:
            first_is_real = True
            first_intersection = get_distance(line, polygon)
    else:
        for point in line:
            if d * (x1 * point[1] - y1 * point[0] + point[0] * y1 - point[1] * x1) == 0:
                second_is_real = True
                second_intersection = get_distance(point, polygon)
                break

        if not second_is_real:
            # Line does not intersect polygon
            return 0.0

        if get_distance((x1, y1), line) <= 1e-10:
            first_is_real = True
            first_intersection = get_distance(line, polygon)

        elif d * (x2 * second_intersection[1] - y2 * second_intersection[0] + second_intersection[0] * y2 - second_intersection[1] * x2) == 0:
            second_is_real = False

        else:
            # Segment is between points
            first_is_real = True
            first_intersection = get_distance(line, polygon)

    # Exit if both intersections are not real
    if not first_is_real and not second_is_real:
        return 0.0

    # If x is real and non-infinitely large, and the intersection is the second one
    if first_is_real and not second_is_real:
        second_is_real = False

    # If x is real and non-infinitely large, and the intersection is the first one
    if second_is_real and not first_is_real:
        first_is_real = False

    # Get a better intersection if it's not degenerate and doesn't make one of lines infinite
    if second_is_real and get_distance((x1, y1), line) <= 1e-10:
        second_is_real = False
    elif first_is_real and get_distance((x2, y2), line) <= 1e-10:
        first_is_real = False

    return min(first_intersection, second_intersection)

n, m = map(int, input().split())
polygon = [(lambda: sys.float_info.max, lambda: sys.float_info.max)(list(map(float, input().split()))) for _ in range(2, n + 2)]
lines = []

for _ in range(m):
    line = [(float("%.2f" % x) for x in map(float, input().split()))]
    lines.append(line)

for line in lines:
    intersection_length = get_intersection_length(polygon, line)
    print(intersection_length)
