from collections import deque

def push_and_pop(index, s):
    while s:
        if not s or s[-1][0] != index:
            s.append((index, index))
        else:
            s.pop()
        index += 1

def find_exterminable_subarrays(s, n):
    subarray_count = 0
    s = deque([(-1, -1)])  # Keeps track of previous index pair
    for i in range(n):
        if i > 0 and s and s[-1][0] + 1 < s[-1][1] - 1:
            # Current index is greater than sum of non-overlapping pairs
            push_and_pop(s[-1][1], s)
        if s:
            subarray_count += i - s[-1][1] + 1
        push_and_pop(i, s)
    return subarray_count

