def push_elements_to_stack(stack, l):
    length = len(stack)
    counter = 0
    for i in range(length, -1, -1):
        if i >= length or stack[i] != i + 1:
            counter += length - i - 1
        elif stack[i] == i + 1:
            counter += 1
    stack.extend([i + 1 for i in range(counter)])
    stack[:length + counter + 1] = stack[length + counter + 1:]

def pop_elements_from_stack(stack):
    length = len(stack)
    counter = 0
    for i in range(length):
        if i >= length:
            break
        if stack[i] == (i + length):
            counter += 1
            stack.pop(i)
        elif stack[i] != i + 1:
            stack[i] = -1
    return counter

def process_subarray(a, length):
