from collections import deque

def is_stack_exterminable(a):
    stack = deque()
    for num in a:
        if not stack or stack[-1] != num:
            stack.append(num)
        else:
            stack.pop()
    return len(stack) == 0

def count_stack_exterminable_subarrays(n, a):
    count = 0
    for i, num in enumerate(a):
        if i == n - 1 or i == 0 or is_stack_exterminable(a[i:], num):
            if i < n - 1 and num == n-1:
                count += 1
        else:
            if a[i-1] == n-1 and a[i+1] == n-1:
                count += 1
    return count

# Example usage
q = int(input())
for _ in range(q):
    n = int(input())
    a = list(map(int, input().split()))
    print(count_stack_exterminable_subarrays(n, a))
