from collections import defaultdict

def extend_dict(d, ranges):
    """Extend dict d by including values from ranges."""
    for start, end in ranges:
        for i in reversed(range(start, end)):
            d[i] = d.get(i, 0) + 1

def count_extended(dict_with_counts, ext_dict):
    """Reduce dict_with_counts according to dict_containing_ones."""
    for k in ext_dict:
        dict_with_counts[k] = dict_with_counts.get(k, 0) + ext_dict[k]

def main():
    n, k = map(int, input().split())
    decks = [defaultdict(int) for _ in range(k)]

    for _ in range(n):
        for i in range(k):
            decks[i][i] += 1
            decks[i][(2 * i + 1) % k] -= 1

    extend_dict(decks, [(1, 2)])
    extend_dict(decks, [(k-1, k)])

    final_decks = defaultdict(int)

    for j in range(2 * k - 2):  # Generate all cards
        lhs_decks = defaultdict(int)
        for i in range(k):
            if decks[i][j] > 0:
                extend_dict(lhs_decks, [(i, i + 1)])

        extend_dict(final_decks, lhs_decks)

        extend_dict(lhs_decks, [(j + 1, j + 2)])
        extend_dict(lhs_decks, [(2 * j + 1, 2 * j + 2)])

    return sum(final_decks[k] for k in range(1, n + 1))

