from math import gcd

def reduce_to_prime(nums):
    primes = set(gcd.reduce(nums))
    for p in primes:
        if nums.count(p) > (nums + [p]).count(p):
            continue
        res = gcd.reduce(nums + [p])
        nums = nums[:len(nums) - len(nums.count(p))]
        if gcd.reduce(nums) == 1:
            return res
    return gcd.reduce(nums)

N, M = map(int, input().split())
