import sys

def diamogras(adj):
    max_dist = {}
    parent = {}
    for i in range(1, len(adj) + 1):
        max_dist[i] = 0
        parent[i] = None

    def dfs(node, parent):
        max_dist[node] = 0
        for child in adj[node]:
            if child != parent:
                dfs(child, node)
                if max_dist[child] > max_dist[node]:
                    max_dist[node] = max_dist[child]
                    parent[node] = child
                else:
                    max_dist[node] += max_dist[child] + 1

    count = 0
    for node in range(1, len(adj) + 1):
        dfs(node, -1)
        count += 1
        if count == len(adj) + 1:
            break

    return max_dist

